{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_wrong_status_code",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, c.attr_http_response_status_code client_code, s.service_name callee, s.attr_http_response_status_code server_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Preserve's outgoing POST to seat-service returns 401 at the client in 537 calls, while seat's server spans return 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-preserve-service' AND (attr_status_code='Error' OR attr_http_response_status_code>=400) GROUP BY ALL ORDER BY n DESC",
          "claim": "Preserve's server returns 500 on 537 requests, matching the 401 outgoing calls one-to-one, with its internal controller span also in error."
        }
      ]
    },
    {
      "service": "ts-station-food-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CASE WHEN trace_id IS NOT NULL THEN 'abnormal' END AS src, service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='ts-station-food-service' AND span_name LIKE 'SELECT ts.station_food%' GROUP BY ALL UNION ALL SELECT 'normal', service_name, span_name, attr_span_kind, count(*), round(quantile_cont(duration,0.5)/1e6,2), round(quantile_cont(duration,0.95)/1e6,2) FROM normal_traces WHERE service_name='ts-station-food-service' AND span_name LIKE 'SELECT ts.station_food%' GROUP BY ALL",
          "claim": "Station-food's station_food_store DB call p95 rises from 1.9 ms to 50.6 ms in the abnormal period, while its list query is unchanged."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50, round(quantile_cont(duration,0.95)/1e6,1) p95 FROM abnormal_traces WHERE service_name IN ('ts-station-food-service','ts-food-service') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Station-food's 'SELECT StationFoodStore' span takes about 175 ms p95 and food's server span rises to 295 ms p95, consistent with a slow DB call inside station-food."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT u.service_name, u.span_name, u.attr_http_response_status_code code, count(DISTINCT u.trace_id) traces FROM abnormal_traces u JOIN abnormal_traces p ON p.trace_id=u.trace_id WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' AND p.service_name='ts-preserve-service' AND p.attr_span_kind='Server' AND p.attr_http_response_status_code=500 GROUP BY ALL",
          "claim": "Ui-dashboard's preserve endpoint returns 500 in the same traces where preserve's own server span returns 500."
        }
      ]
    },
    {
      "from": "ts-station-food-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-food-service' AND c.attr_span_kind='Client' AND s.service_name='ts-station-food-service' GROUP BY ALL",
          "claim": "Food-service's client POST calls to station-food-service take about 185 ms p95 and wait on station-food's slow server span."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT u.service_name, f.service_name, count(DISTINCT u.trace_id) traces, round(quantile_cont(f.duration,0.95)/1e6,1) food_p95_ms FROM abnormal_traces u JOIN abnormal_traces f ON f.trace_id=u.trace_id WHERE u.service_name='ts-ui-dashboard' AND u.span_name LIKE '%foodservice%' AND f.service_name='ts-food-service' AND f.attr_span_kind='Server' GROUP BY ALL",
          "claim": "User-facing ui-dashboard food requests share traces with food-service server spans whose p95 is about 295 ms."
        }
      ]
    }
  ]
}
